deepml motion 0.3
module corpus.deepml_motion.example_03001
policy deterministic
policy no_network
skeleton Rig03001 { joint Root parent none joint Hip parent Root joint FootL parent Hip joint FootR parent Hip }
procedural animation Procedural03001 seed 3001 {
  trajectory = predict_trajectory(velocity, horizon=1.0s)
  match = motion_match(database="local:motions_4", trajectory=trajectory)
  constrain contact FootL to ground when phase < 0.5
  constrain contact FootR to ground when phase >= 0.5
}
layered state_machine Layers03001 { base: Locomotion upper: Gesture additive: Breathing }
synchronize Procedural03001 with scene.Actor9 and timeline.Sequence11

